    "from prophet import Prophet\n",
    "import warnings\n",
    "warnings.filterwarnings('ignore')\n",
    "\n",
    "print(\"=\" * 55)\n",
    "print(\"   DEMAND FORECAST — Next 4 weeks\")\n",
    "print(\"=\" * 55)\n",
    "\n",
    "risk_skus = ['SKU34', 'SKU47', 'SKU68']\n",
    "\n",
    "for sku in risk_skus:\n",
    "    row = df[df['SKU'] == sku].iloc[0]\n",
    "    \n",
    "    import numpy as np\n",
    "    np.random.seed(42)\n",
    "    \n",
    "    weeks = pd.date_range('2023-01-01', periods=52, freq='W')\n",
    "    base_demand = row['Number of products sold'] / 4\n",
    "    \n",
    "    weekly_demand = pd.DataFrame({\n",
    "        'ds': weeks,\n",
    "        'y': base_demand + np.random.randint(-10, 15, 52)\n",
    "    })\n",
    "    \n",
    "    model = Prophet(weekly_seasonality=True,\n",
    "                   yearly_seasonality=False,\n",
    "                   daily_seasonality=False)\n",
    "    model.fit(weekly_demand)\n",
    "    \n",
    "    future = model.make_future_dataframe(periods=4, freq='W')\n",
    "    forecast = model.predict(future)\n",
    "    \n",
    "    next_4_weeks = forecast.tail(4)[['ds', 'yhat']].copy()\n",
    "    next_4_weeks['yhat'] = next_4_weeks['yhat'].round(0)\n",
    "    total_forecast = next_4_weeks['yhat'].sum()\n",
    "    \n",
    "    print(f\"\\n📦 {sku} | {row['Product type'].upper()}\")\n",
    "    print(f\"   Current stock: {row['Stock levels']} units\")\n",
    "    print(f\"   Forecasted demand next 4 weeks:\")\n",
    "    for _, frow in next_4_weeks.iterrows():\n",
